// src/pages/StudentDashboard.jsx
import { useState, useEffect, useContext } from "react";
import { useNavigate } from "react-router-dom";
import api from "../api";
import { AuthContext } from "../contexts/AuthContext";

// Card Component
const Card = ({ title, children }) => (
  <div
    style={{
      background: "#fff",
      padding: "20px",
      borderRadius: "12px",
      boxShadow: "0 4px 12px rgba(0,0,0,0.08)",
      marginBottom: "20px",
    }}
  >
    <h2 style={{ marginBottom: "15px", color: "#007bff" }}>{title}</h2>
    {children}
  </div>
);

export default function StudentDashboard() {
  const [stats, setStats] = useState({
    totalCandidates: 0,
    totalElections: 0,
    hasVoted: false,
  });
  const [candidates, setCandidates] = useState([]);
  const [elections, setElections] = useState([]);
  const [selectedElection, setSelectedElection] = useState(null);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [activeTab, setActiveTab] = useState("Candidates");
  const [message, setMessage] = useState("");

  const { user, logout, token } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleApiError = (err) => {
    console.error(err);
    if (err.response?.status === 401) {
      logout();
      navigate("/login");
    } else {
      setMessage(err.response?.data?.error || err.message);
    }
  };

  // ---------------- API Calls ----------------
  const fetchStats = async () => {
    try {
      const [candidatesRes, electionsRes, voteRes] = await Promise.all([
        api.get("/candidates"),
        api.get("/elections"),
        api.get("/my-votes"),
      ]);

      setStats({
        totalCandidates: candidatesRes.data.length,
        totalElections: electionsRes.data.length,
        hasVoted: voteRes.data.hasVoted,
      });
      setCandidates(candidatesRes.data);
      setElections(electionsRes.data);
      if (electionsRes.data.length > 0) setSelectedElection(electionsRes.data[0].id);
    } catch (err) {
      handleApiError(err);
    }
  };

  useEffect(() => {
    if (!token) { navigate("/login"); return; }
    fetchStats();
  }, [token]);

  const handleElectionChange = (id) => {
    setSelectedElection(id);
  };

  const castVote = async (candidateId) => {
    try {
      await api.post("/vote", { candidateId, electionId: selectedElection });
      setMessage("Vote cast successfully!");
      setStats(prev => ({ ...prev, hasVoted: true }));
    } catch (err) {
      handleApiError(err);
    }
  };

  // ---------------- Rendered Sections ----------------
  const renderContent = () => {
    switch (activeTab) {
      case "Candidates":
        return (
          <Card title="Candidates">
            {candidates.length === 0 ? (
              <p style={{ color: "#777", fontStyle: "italic" }}>No candidates available.</p>
            ) : (
              <table style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead>
                  <tr style={{ background: "#f1f1f1" }}>
                    <th style={{ padding: "8px", textAlign: "left" }}>Name</th>
                    <th style={{ padding: "8px", textAlign: "left" }}>Position</th>
                    <th style={{ padding: "8px", textAlign: "left" }}>Party</th>
                    <th style={{ padding: "8px", textAlign: "center" }}>Action</th>
                  </tr>
                </thead>
                <tbody>
                  {candidates.map(c => (
                    <tr key={c.id} style={{ borderTop: "1px solid #eee" }}>
                      <td style={{ padding: "8px" }}>{c.name}</td>
                      <td style={{ padding: "8px" }}>{c.position}</td>
                      <td style={{ padding: "8px" }}>{c.party || "-"}</td>
                      <td style={{ padding: "8px", textAlign: "center" }}>
                        <button
                          onClick={() => castVote(c.id)}
                          disabled={stats.hasVoted}
                          style={{
                            padding: "5px 10px",
                            borderRadius: "6px",
                            border: "none",
                            background: stats.hasVoted ? "#6c757d" : "#28a745",
                            color: "#fff",
                            cursor: stats.hasVoted ? "not-allowed" : "pointer",
                          }}
                        >
                          {stats.hasVoted ? "Already Voted" : "Vote"}
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </Card>
        );
      case "Elections":
        return (
          <Card title="Elections">
            {elections.length === 0 ? (
              <p style={{ color: "#777", fontStyle: "italic" }}>No elections available.</p>
            ) : (
              <table style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead>
                  <tr style={{ background: "#f1f1f1" }}>
                    <th style={{ padding: "8px", textAlign: "left" }}>Election Name</th>
                    <th style={{ padding: "8px", textAlign: "left" }}>Start Date</th>
                    <th style={{ padding: "8px", textAlign: "left" }}>End Date</th>
                  </tr>
                </thead>
                <tbody>
                  {elections.map(el => (
                    <tr key={el.id} style={{ borderTop: "1px solid #eee" }}>
                      <td style={{ padding: "8px" }}>{el.name}</td>
                      <td style={{ padding: "8px" }}>{new Date(el.startsAt).toLocaleString()}</td>
                      <td style={{ padding: "8px" }}>{new Date(el.endsAt).toLocaleString()}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </Card>
        );
      case "Stats":
        return (
          <Card title="Dashboard Stats">
            <p>Total Candidates: {stats.totalCandidates}</p>
            <p>Total Elections: {stats.totalElections}</p>
            <p>Voting Status: {stats.hasVoted ? "Voted ✅" : "Not Voted ❌"}</p>
          </Card>
        );
      default: return null;
    }
  };

  return (
    <div style={{ display: "flex", minHeight: "100vh", fontFamily: "Arial, sans-serif", backgroundColor: "#f4f6f8" }}>
      {/* Sidebar */}
      <aside style={{
        width: sidebarOpen ? "220px" : "60px",
        transition: "width 0.3s",
        background: "#343a40",
        color: "#fff",
        paddingTop: "20px",
        display: "flex",
        flexDirection: "column",
      }}>
        <button onClick={() => setSidebarOpen(!sidebarOpen)} style={{ background: "none", border: "none", color: "#fff", cursor: "pointer", padding: "10px", fontSize: "1.2rem", marginBottom: "20px" }}>☰</button>
        <nav style={{ display: "flex", flexDirection: "column", gap: "10px", paddingLeft: sidebarOpen ? "20px" : "0" }}>
          <span style={{ cursor: "pointer", fontWeight: activeTab === "Stats" ? "bold" : "normal" }} onClick={() => setActiveTab("Stats")}>📊 Dashboard</span>
          <span style={{ cursor: "pointer", fontWeight: activeTab === "Candidates" ? "bold" : "normal" }} onClick={() => setActiveTab("Candidates")}>👤 Candidates</span>
          <span style={{ cursor: "pointer", fontWeight: activeTab === "Elections" ? "bold" : "normal" }} onClick={() => setActiveTab("Elections")}>🏛 Elections</span>
          <button onClick={() => { logout(); navigate("/login"); }} style={{ marginTop: "auto", padding: "10px", borderRadius: "6px", border: "none", background: "#dc3545", color: "#fff", cursor: "pointer", fontWeight: "bold", marginLeft: sidebarOpen ? "20px" : "0" }}>Logout</button>
        </nav>
      </aside>

      {/* Main Content */}
      <main style={{ flexGrow: 1, padding: "30px", maxWidth: "1000px", margin: "0 auto" }}>
        {renderContent()}
        {message && <p style={{ textAlign: "center", color: message.toLowerCase().includes("fail") ? "red" : "green", fontWeight: "bold", marginTop: "20px" }}>{message}</p>}
      </main>
    </div>
  );
}
